/**
 * `@analyzr/client`: typed REST client for the analyzr API, generated by hey-api
 * from the OpenAPI document of `@analyzr/contracts` (`pnpm --filter
 * @analyzr/client generate`; never edit `src/generated` by hand).
 *
 * @example
 * const client = createAnalyzrClient({ baseUrl: 'http://127.0.0.1:7400', token });
 * const { data, error } = await listProjects({ client });
 */
import { createClient, createConfig, type Client } from './generated/client/index.ts';

export * from './generated/index.ts';
export type { Client } from './generated/client/index.ts';

/** Where a local analyzr listens by default (CONCEPT §6, docker/compose.yaml). */
export const DEFAULT_ANALYZR_URL = 'http://127.0.0.1:7400';

export interface AnalyzrClientOptions {
  /** Server origin, e.g. `http://127.0.0.1:7400`; the SDK adds `/api/v1/...`. */
  baseUrl?: string;
  /** Agent token (`analyzr_at_…`), sent as `Authorization: Bearer`. Omit for the local owner session. */
  token?: string;
  /** Custom fetch, e.g. for tests. */
  fetch?: typeof globalThis.fetch;
}

/** Creates an independent client instance; pass it as `{ client }` to the SDK functions. */
export function createAnalyzrClient(options: AnalyzrClientOptions = {}): Client {
  return createClient(
    createConfig({
      baseUrl: (options.baseUrl ?? DEFAULT_ANALYZR_URL).replace(/\/+$/, ''),
      ...(options.token === undefined ? {} : { auth: options.token }),
      ...(options.fetch === undefined ? {} : { fetch: options.fetch }),
    }),
  );
}
